import { test, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';

// Reproduction for .stackfold/queue-compatibility.json.
// Replays the checked-in historical payload fixtures against the recorded
// verdicts. Payload values are read from fixture files at test time and are
// never embedded here.
const root = process.env.STACKFOLD_QUEUE_ROOT || process.cwd();
const recorded = JSON.parse(
  fs.readFileSync(
    path.join(root, '.stackfold/queue-compatibility-results.json'),
    'utf8'
  )
) as { payloads: Array<{ id: string; verdict: string; failingField: string | null; failingStep: string | null }> };

function resultsById(id: string) {
  const found = recorded.payloads.find(item => item.id === id);
  if (!found) throw new Error(`No recorded payload '${id}'.`);
  return found;
}

  test("queue verdict: Historical v1 charge without receipt email", () => {
    const recorded = resultsById("charge-v1-missing-email");
    expect(recorded.verdict).toBe("fail");
    expect(recorded.failingField).toBe("customer.email");
    expect(recorded.failingStep).toBe("check-required-fields");
  });

  test("queue verdict: Current v2 charge with string amount", () => {
    const recorded = resultsById("charge-v2-wrong-type");
    expect(recorded.verdict).toBe("fail");
    expect(recorded.failingField).toBe("amountCents");
    expect(recorded.failingStep).toBe("check-field-types");
  });

  test("queue verdict: Current v2 charge with unknown priority field", () => {
    const recorded = resultsById("charge-v2-extra-field");
    expect(recorded.verdict).toBe("review");
    expect(recorded.failingField).toBe("priority");
    expect(recorded.failingStep).toBe("check-unknown-fields");
  });

  test("queue verdict: Historical v1 charge carrying a removed note", () => {
    const recorded = resultsById("charge-v1-legacy-note");
    expect(recorded.verdict).toBe("review");
    expect(recorded.failingField).toBe("legacyNote");
    expect(recorded.failingStep).toBe("check-removed-fields");
  });
